#!/usr/bin/env bash
# Build the feature-selected FFmpeg backend for the HOST (development/testing).
#
# Contract:
#   tools/ffmpeg-builder/build-host.sh
#   env: VELMUX_FFMPEG_JOBS=<parallel jobs> (default: nproc)
#
# Idempotent: exits 0 quickly when the output is already present.
# Output layout:
#   out/host/include, out/host/lib (static), out/host/lib/pkgconfig,
#   out/host/bin/{ffmpeg,ffprobe,velmux-ffmpeg-probe},
#   out/host/share/velmux/ffmpeg-capabilities.json (machine-readable manifest
#   generated by running the probe against the actual built libraries).
set -euo pipefail

. "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/lib.sh"

HOST_OUT="$OUT_DIR/host"
HOST_PREFIX="$HOST_OUT"

require_tool curl
require_tool make
require_tool gcc
require_tool python3
ensure_cmake_ninja
ensure_meson

# Complete-artifact check: every library of the feature-selected stack plus
# FFmpeg and the manifest. A partial prefix (interrupted build, tainted
# environment) rebuilds instead of masquerading as complete. zlib is exempt:
# the host build intentionally uses the system zlib when available.
host_build_complete() {
  local lib
  for lib in libx264.a libmp3lame.a libopus.a libogg.a libvorbis.a \
             libvpx.a libdav1d.a libSvtAv1Enc.a libfreetype.a libpng16.a \
             libharfbuzz.a libfribidi.a libass.a libavcodec.a libavformat.a \
             libavutil.a libavfilter.a libswscale.a libswresample.a; do
    [ -f "$HOST_PREFIX/lib/$lib" ] || return 1
  done
  [ -f "$HOST_PREFIX/lib/pkgconfig/libavcodec.pc" ] || return 1
  [ -f "$HOST_PREFIX/share/velmux/ffmpeg-capabilities.json" ] || return 1
  return 0
}

# Build identity over every input that determines the artifact contents.
HOST_IDENTITY="$(compute_identity host)"

if host_build_complete && identity_matches "$HOST_PREFIX" "$HOST_IDENTITY"; then
  log "host build up to date (identity verified)"
  fixup_pkgconfig_prefix "$HOST_PREFIX"
  exit 0
fi

# When the recorded identity of an existing (possibly incomplete or stale)
# prefix does not match the current tree, wipe it so the per-library
# "already installed" checks below cannot silently mix artifacts from
# different builder/versions generations.
if [ -d "$HOST_PREFIX" ] && ! identity_matches "$HOST_PREFIX" "$HOST_IDENTITY"; then
  log "recorded build identity does not match the current tree; rebuilding from scratch"
  rm -rf "$HOST_PREFIX"
fi

mkdir -p "$HOST_PREFIX" "$SRC_DIR"
BUILD_TMP="$SRC_DIR/build-host"
mkdir -p "$BUILD_TMP"

# ---------------------------------------------------------------------------
# Dependencies (host). System zlib is used when available, otherwise built
# from the pinned source.
# ---------------------------------------------------------------------------

# --- nasm (assembler; required by x264 and FFmpeg x86 asm on host) -----------
nasm_tb="$(fetch_tarball nasm)"
nasm_src="$(extract_tarball "$nasm_tb")"
if [ ! -x "$HOST_PREFIX/bin/nasm" ]; then
  log "building nasm"
  (cd "$nasm_src" && ./configure --prefix="$HOST_PREFIX" >/dev/null && \
   make -j"$JOBS" >/dev/null && make install >/dev/null)
  log "nasm installed"
fi
# Make the freshly built assembler visible to x264/FFmpeg configure steps.
export PATH="$HOST_PREFIX/bin:$PATH"
ZLIB_PC=""
if host_has_system zlib; then
  log "using system zlib ($(pkg-config --modversion zlib))"
else
  log "building zlib from source"
  zlib_tb="$(fetch_tarball zlib)"
  zlib_src="$(extract_tarball "$zlib_tb")"
  zlib_build="$BUILD_TMP/zlib"
  mkdir -p "$zlib_build"
  (cd "$zlib_build" && cmake -G Ninja -DCMAKE_BUILD_TYPE=Release \
     -DCMAKE_INSTALL_PREFIX="$HOST_PREFIX" "$zlib_src" >/dev/null && \
   cmake --build . >/dev/null && cmake --install . >/dev/null)
  ZLIB_PC="$HOST_PREFIX/lib/pkgconfig"
  log "zlib installed to $HOST_PREFIX"
fi

# --- x264 (H.264 software encoder) ------------------------------------------
x264_tb="$(fetch_tarball x264)"
x264_src="$(extract_tarball "$x264_tb")"
if [ ! -f "$HOST_PREFIX/lib/libx264.a" ]; then
  log "building x264"
  (cd "$x264_src" && ./configure --prefix="$HOST_PREFIX" \
     --disable-cli --enable-static --enable-pic --disable-opencl >/dev/null && \
   make -j"$JOBS" >/dev/null && make install >/dev/null)
  log "x264 installed"
fi

# --- lame (MP3) ---------------------------------------------------------------
lame_tb="$(fetch_tarball lame)"
lame_src="$(extract_tarball "$lame_tb")"
if [ ! -f "$HOST_PREFIX/lib/libmp3lame.a" ]; then
  log "building lame"
  (cd "$lame_src" && ./configure --prefix="$HOST_PREFIX" \
     --disable-shared --enable-static --disable-dependency-tracking \
     --disable-frontend >/dev/null && \
   make -j"$JOBS" >/dev/null && make install >/dev/null)
  log "lame installed"
fi

# --- opus ---------------------------------------------------------------------
opus_tb="$(fetch_tarball opus)"
opus_src="$(extract_tarball "$opus_tb")"
if [ ! -f "$HOST_PREFIX/lib/libopus.a" ]; then
  log "building opus"
  (cd "$opus_src" && ./configure --prefix="$HOST_PREFIX" \
     --disable-shared --enable-static --disable-doc --disable-extra-programs >/dev/null && \
   make -j"$JOBS" >/dev/null && make install >/dev/null)
  log "opus installed"
fi

# --- libogg + libvorbis -------------------------------------------------------
ogg_tb="$(fetch_tarball libogg)"
ogg_src="$(extract_tarball "$ogg_tb")"
if [ ! -f "$HOST_PREFIX/lib/libogg.a" ]; then
  log "building libogg"
  (cd "$ogg_src" && ./configure --prefix="$HOST_PREFIX" \
     --disable-shared --enable-static >/dev/null && \
   make -j"$JOBS" >/dev/null && make install >/dev/null)
  log "libogg installed"
fi
vorbis_tb="$(fetch_tarball libvorbis)"
vorbis_src="$(extract_tarball "$vorbis_tb")"
if [ ! -f "$HOST_PREFIX/lib/libvorbis.a" ]; then
  log "building libvorbis"
  (cd "$vorbis_src" && ./configure --prefix="$HOST_PREFIX" \
     --disable-shared --enable-static --disable-docs >/dev/null && \
   make -j"$JOBS" >/dev/null && make install >/dev/null)
  log "libvorbis installed"
fi

# --- libvpx (VP8/VP9) ---------------------------------------------------------
vpx_tb="$(fetch_tarball libvpx)"
vpx_src="$(extract_tarball "$vpx_tb")"
if [ ! -f "$HOST_PREFIX/lib/libvpx.a" ]; then
  log "building libvpx"
  (cd "$vpx_src" && ./configure --prefix="$HOST_PREFIX" \
     --disable-shared --enable-static --enable-pic \
     --disable-unit-tests --disable-examples --disable-tools --disable-docs \
     --disable-install-docs --disable-webm-io >/dev/null && \
   make -j"$JOBS" >/dev/null && make install >/dev/null)
  log "libvpx installed"
fi

# --- dav1d (AV1 decoder, meson) ------------------------------------------------
dav1d_tb="$(fetch_tarball dav1d)"
dav1d_src="$(extract_tarball "$dav1d_tb")"
if [ ! -f "$HOST_PREFIX/lib/x86_64-linux-gnu/libdav1d.a" ] && [ ! -f "$HOST_PREFIX/lib/libdav1d.a" ]; then
  log "building dav1d"
  dav1d_build="$BUILD_TMP/dav1d"
  rm -rf "$dav1d_build"
  # --libdir=lib: Debian meson defaults to lib/<triple> for NATIVE installs,
  # which would hide the .pc files from consumers that only search
  # $prefix/lib/pkgconfig (libass, FFmpeg configure). Force the flat layout.
  meson setup "$dav1d_build" "$dav1d_src" \
    --prefix="$HOST_PREFIX" --libdir=lib \
    --default-library=static --buildtype=release \
    -Denable_tools=false -Denable_tests=false >/dev/null
  ninja -C "$dav1d_build" >/dev/null
  meson install -C "$dav1d_build" >/dev/null
  log "dav1d installed"
fi

# --- SVT-AV1 (AV1 software encoder, cmake) -------------------------------------
svt_tb="$(fetch_tarball svt-av1)"
svt_src="$(extract_tarball "$svt_tb")"
if [ ! -f "$HOST_PREFIX/lib/libSvtAv1Enc.a" ]; then
  log "building SVT-AV1"
  svt_build="$BUILD_TMP/svt-av1"
  rm -rf "$svt_build"
  # CMAKE_POLICY_VERSION_MINIMUM: SVT-AV1 2.3.0's CMakeLists predates CMake 4's
  # removal of <3.5 policy compatibility; this is the official escape hatch.
  cmake -G Ninja -S "$svt_src" -B "$svt_build" \
    -DCMAKE_BUILD_TYPE=Release -DCMAKE_INSTALL_PREFIX="$HOST_PREFIX" \
    -DBUILD_SHARED_LIBS=OFF -DBUILD_TESTING=OFF \
    -DCMAKE_POLICY_VERSION_MINIMUM=3.5 >/dev/null
  cmake --build "$svt_build" >/dev/null
  cmake --install "$svt_build" >/dev/null
  log "SVT-AV1 installed"
fi

# --- freetype (libass dependency chain) -----------------------------------------
ft_tb="$(fetch_tarball freetype)"
ft_src="$(extract_tarball "$ft_tb")"
if [ ! -f "$HOST_PREFIX/lib/libfreetype.a" ]; then
  log "building freetype"
  ft_build="$BUILD_TMP/freetype"
  rm -rf "$ft_build"
  cmake -G Ninja -S "$ft_src" -B "$ft_build" \
    -DCMAKE_BUILD_TYPE=Release -DCMAKE_INSTALL_PREFIX="$HOST_PREFIX" \
    -DBUILD_SHARED_LIBS=OFF -DFT_DISABLE_ZLIB=FALSE \
    -DFT_REQUIRE_ZLIB=TRUE -DFT_DISABLE_BZIP2=TRUE -DFT_DISABLE_BROTLI=TRUE \
    -DFT_DISABLE_HARFBUZZ=TRUE >/dev/null
  cmake --build "$ft_build" >/dev/null
  cmake --install "$ft_build" >/dev/null
  log "freetype installed"
fi

# --- libpng (only needed by freetype on some configs; built for completeness) ---
png_tb="$(fetch_tarball libpng)"
png_src="$(extract_tarball "$png_tb")"
if [ ! -f "$HOST_PREFIX/lib/libpng16.a" ]; then
  log "building libpng"
  png_build="$BUILD_TMP/libpng"
  rm -rf "$png_build"
  cmake -G Ninja -S "$png_src" -B "$png_build" \
    -DCMAKE_BUILD_TYPE=Release -DCMAKE_INSTALL_PREFIX="$HOST_PREFIX" \
    -DBUILD_SHARED_LIBS=OFF -DPNG_TESTS=OFF -DPNG_TOOLS=OFF \
    -DPNG_SHARED=OFF -DPNG_EXECUTABLES=OFF >/dev/null
  cmake --build "$png_build" >/dev/null
  cmake --install "$png_build" >/dev/null
  log "libpng installed"
fi

# --- harfbuzz (no glib) ----------------------------------------------------------
hb_tb="$(fetch_tarball harfbuzz)"
hb_src="$(extract_tarball "$hb_tb")"
if [ ! -f "$HOST_PREFIX/lib/libharfbuzz.a" ]; then
  log "building harfbuzz"
  hb_build="$BUILD_TMP/harfbuzz"
  rm -rf "$hb_build"
  cmake -G Ninja -S "$hb_src" -B "$hb_build" \
    -DCMAKE_BUILD_TYPE=Release -DCMAKE_INSTALL_PREFIX="$HOST_PREFIX" \
    -DBUILD_SHARED_LIBS=OFF -DHB_BUILD_UTILS=OFF -DHB_BUILD_TESTS=OFF \
    -DHB_HAVE_GLIB=OFF -DHB_HAVE_FREETYPE=ON >/dev/null
  cmake --build "$hb_build" >/dev/null
  cmake --install "$hb_build" >/dev/null
  log "harfbuzz installed"
fi

# --- fribidi ------------------------------------------------------------------------
fribidi_tb="$(fetch_tarball fribidi)"
fribidi_src="$(extract_tarball "$fribidi_tb")"
if [ ! -f "$HOST_PREFIX/lib/libfribidi.a" ]; then
  log "building fribidi"
  fribidi_build="$BUILD_TMP/fribidi"
  rm -rf "$fribidi_build"
  meson setup "$fribidi_build" "$fribidi_src" \
    --prefix="$HOST_PREFIX" --libdir=lib \
    --default-library=static --buildtype=release \
    -Ddocs=false -Dtests=false >/dev/null
  ninja -C "$fribidi_build" >/dev/null
  meson install -C "$fribidi_build" >/dev/null
  log "fribidi installed"
fi

# --- libass ----------------------------------------------------------------------------
ass_tb="$(fetch_tarball libass)"
ass_src="$(extract_tarball "$ass_tb")"
if [ ! -f "$HOST_PREFIX/lib/libass.a" ]; then
  log "building libass"
  (cd "$ass_src" && ./configure --prefix="$HOST_PREFIX" \
     --disable-shared --enable-static \
     --disable-fontconfig --disable-require-system-font-provider \
     PKG_CONFIG_PATH="$HOST_PREFIX/lib/pkgconfig:${PKG_CONFIG_PATH:-}" >/dev/null && \
   make -j"$JOBS" >/dev/null && make install >/dev/null)
  log "libass installed"
fi

# ---------------------------------------------------------------------------
# FFmpeg itself.
# NOTE: nasm (built above) enables x86 asm. Conversion is local-file only, so
# --disable-network reduces attack surface. libavdevice is intentionally
# excluded (spec: no V1 requirement for it).
# ---------------------------------------------------------------------------
ffmpeg_tb="$(fetch_ffmpeg)"
ffmpeg_src="$(extract_tarball "$ffmpeg_tb")"
FFBUILD="$SRC_DIR/build-host/ffmpeg"
if [ ! -f "$HOST_PREFIX/lib/libavcodec.a" ]; then
  log "configuring FFmpeg (host)"
  rm -rf "$FFBUILD"
  mkdir -p "$FFBUILD"
  # Meson-built deps (dav1d, fribidi) land in a Debian multiarch libdir;
  # add it to the search path when present. lame ships no pkg-config file,
  # so explicit -L/-I flags cover it.
  EXTRA_LIBDIR=""
  for d in "$HOST_PREFIX"/lib/*-linux-gnu; do
    if [ -d "$d" ]; then
      EXTRA_LIBDIR="$d"
      break
    fi
  done
  export PKG_CONFIG_PATH="$HOST_PREFIX/lib/pkgconfig:${EXTRA_LIBDIR:+$EXTRA_LIBDIR/pkgconfig}${PKG_CONFIG_PATH:+:$PKG_CONFIG_PATH}"
  EXTRA_LDFLAGS="-L$HOST_PREFIX/lib"
  if [ -n "$EXTRA_LIBDIR" ]; then
    EXTRA_LDFLAGS="$EXTRA_LDFLAGS -L$EXTRA_LIBDIR"
  fi
  (cd "$FFBUILD" && "$ffmpeg_src/configure" \
     --prefix="$HOST_PREFIX" \
     --pkg-config-flags=--static \
     --extra-cflags="-I$HOST_PREFIX/include" \
     --extra-ldflags="$EXTRA_LDFLAGS" \
     --disable-shared --enable-static \
     --disable-debug --disable-doc \
     --disable-ffplay \
     --disable-network \
     --disable-avdevice \
     --disable-autodetect \
     --enable-pthreads \
     --enable-gpl --enable-libx264 \
     --enable-libmp3lame \
     --enable-libopus \
     --enable-libvorbis \
     --enable-libvpx \
     --enable-libdav1d \
     --enable-libsvtav1 \
     --enable-libfreetype \
     --enable-libharfbuzz \
     --enable-libfribidi \
     --enable-libass \
     --enable-zlib \
     --enable-protocol=file \
     --enable-protocol=pipe \
     >/dev/null)
  log "building FFmpeg (host) with $JOBS jobs"
  (cd "$FFBUILD" && make -j"$JOBS" >/dev/null && make install >/dev/null)
  log "FFmpeg installed to $HOST_PREFIX"
fi

# ---------------------------------------------------------------------------
# Capability manifest: compile the probe against the built libraries and run
# it. The manifest reflects the ACTUAL compiled build, not assumptions.
# ---------------------------------------------------------------------------
PROBE_SRC="$BUILDER_ROOT/probe/velmux-ffmpeg-probe.c"
PROBE_BIN="$HOST_PREFIX/bin/velmux-ffmpeg-probe"
MANIFEST="$HOST_PREFIX/share/velmux/ffmpeg-capabilities.json"
if [ ! -f "$MANIFEST" ] || [ "$PROBE_SRC" -nt "$MANIFEST" ]; then
  log "building capability probe"
  mkdir -p "$HOST_PREFIX/bin" "$HOST_PREFIX/share/velmux"
  with_pkg_config "$HOST_PREFIX" gcc -O2 -o "$PROBE_BIN" "$PROBE_SRC" \
    $(with_pkg_config "$HOST_PREFIX" pkg-config --cflags --static \
      libavcodec libavformat libavutil) \
    $(with_pkg_config "$HOST_PREFIX" pkg-config --libs --static \
      libavcodec libavformat libavutil)
  log "generating capability manifest"
  "$PROBE_BIN" > "$MANIFEST"
  python3 -c "import json,sys; d=json.load(open('$MANIFEST')); print('probe OK: %d decoders, %d encoders, %d muxers, %d demuxers' % (len(d['decoders']), len(d['encoders']), len(d['muxers']), len(d['demuxers'])))"
fi

# ---------------------------------------------------------------------------
# Validate the real build against the Velmux feature requirements.
# ---------------------------------------------------------------------------
log "validating build"
python3 "$BUILDER_ROOT/validate.py" "$MANIFEST"

# Final gate: every library, the pkg-config files and the capability
# manifest must be present, and the identity must be recorded.
host_build_complete || die "host build finished but the artifact is incomplete"
write_identity "$HOST_PREFIX" "$HOST_IDENTITY" \
  "host FFmpeg ($(uname -srm)), jobs=$JOBS"
fixup_pkgconfig_prefix "$HOST_PREFIX"

log "host build complete: $HOST_PREFIX"
